<?php
declare(strict_types=1);
require_once __DIR__ . '/../../config/config.php';
require_once __DIR__ . '/../../config/database.php';
require_once __DIR__ . '/../../config/functions.php';
require_once __DIR__ . '/../../config/session.php';
Session::start();
$userRole=Session::getUserRole();
if(!Session::isLoggedIn()||!in_array($userRole,['hr_manager','hr_staff','admin'])){header('Location: '.APP_URL.'index.php');exit();}
$selected_date=$_GET['date']??date('Y-m-d'); $message=''; $msg_type='success';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $action=$_POST['action']??''; $emp_id=(int)($_POST['employee_id']??0);
    try{
        if($action==='check_in'){
            $work_mode=$_POST['work_mode']??'remote'; $check_in_time=date('H:i:s');
            dbExecute("INSERT INTO attendance (employee_id, date, check_in, work_mode, status) VALUES (?, ?, ?, ?, 'present') ON DUPLICATE KEY UPDATE check_in = VALUES(check_in), work_mode = VALUES(work_mode), status = 'present'",[$emp_id,$selected_date,$check_in_time,$work_mode]);
            $message=t('hr.attendance_recorded');
        }elseif($action==='check_out'){
            dbExecute("UPDATE attendance SET check_out = ? WHERE employee_id = ? AND date = ?",[date('H:i:s'),$emp_id,$selected_date]); $message=t('hr.checkout_recorded');
        }elseif($action==='mark_absent'){
            dbExecute("INSERT INTO attendance (employee_id, date, status) VALUES (?, ?, 'absent') ON DUPLICATE KEY UPDATE status = 'absent'",[$emp_id,$selected_date]); $message=t('hr.absence_recorded');
        }elseif($action==='mark_leave'){
            dbExecute("INSERT INTO attendance (employee_id, date, status) VALUES (?, ?, 'on_leave') ON DUPLICATE KEY UPDATE status = 'on_leave'",[$emp_id,$selected_date]); $message=t('hr.attendance_leave_recorded');
        }
    }catch(Throwable $e){$message=t('hr.attendance_error',['message'=>$e->getMessage()]);$msg_type='error';}
}
$employees=dbFetchAll("SELECT e.id,e.full_name,e.department_id,d.name_ar as dept_name FROM employees e LEFT JOIN departments d ON e.department_id=d.id WHERE e.status='active' ORDER BY e.full_name",[]);
$attendance_records=[]; $att_list=dbFetchAll("SELECT * FROM attendance WHERE date = ?",[$selected_date]);
foreach($att_list as $att)$attendance_records[$att['employee_id']]=$att;
$stats=['present'=>0,'absent'=>0,'late'=>0,'on_leave'=>0,'remote'=>0,'onsite'=>0];
foreach($attendance_records as $att){if(isset($stats[$att['status']]))$stats[$att['status']]++;if(isset($stats[$att['work_mode']]))$stats[$att['work_mode']]++;}
$pageTitle=t('hr.attendance_title'); require_once __DIR__.'/../../includes/header.php';
?>
<style>
