er{background:#f8dce0}.action-leave{background:#fff6d9;color:#806000}.action-leave:hover{background:#ffefbf}.complete{font-size:.72rem;color:#98a2b3;display:inline-flex;align-items:center;gap:5px}.empty-row{text-align:center;padding:35px!important;color:#98a2b3}.empty-row i{font-size:1.5rem;display:block;margin-bottom:7px}
@media(max-width:1000px){.att-summary{grid-template-columns:repeat(2,1fr)}.att-table th:nth-child(2),.att-table td:nth-child(2){display:none}.action-cell{min-width:175px}}@media(max-width:700px){.att-summary{grid-template-columns:1fr 1fr}.att-hero{padding:16px}.date-nav{width:100%;margin-top:12px}.date-nav .date-box{flex:1}.att-table th:nth-child(5),.att-table td:nth-child(5){display:none}.att-panel{overflow-x:auto}.att-table{min-width:760px}}
