<div class="att-page">
<div class="att-hero"><div class="d-flex justify-content-between align-items-center flex-wrap gap-3"><div><h1><i class="fas fa-user-clock me-2" style="color:#1b4d8f"></i><?php echo e(t('hr.attendance_title')); ?></h1><p><?php echo e(t('hr.attendance_intro',['date'=>date('Y-m-d',strtotime($selected_date))])); ?></p></div><div class="date-nav"><a class="btn" href="?date=<?php echo htmlspecialchars(date('Y-m-d',strtotime($selected_date.' -1 day'))); ?>" title="<?php echo e(t('hr.previous_day')??'اليوم السابق'); ?>"><i class="fas fa-chevron-right"></i></a><form method="GET" class="m-0"><input type="date" name="date" class="form-control date-box" value="<?php echo htmlspecialchars($selected_date); ?>" onchange="this.form.submit()"></form><a class="btn" href="?date=<?php echo htmlspecialchars(date('Y-m-d',strtotime($selected_date.' +1 day'))); ?>" title="<?php echo e(t('hr.next_day')??'اليوم التالي'); ?>"><i class="fas fa-chevron-left"></i></a></div></div></div>
<?php if($message): ?><div class="alert alert-<?php echo $msg_type==='error'?'danger':'success'; ?> py-2 px-3 mb-3" style="border-radius:9px;font-size:.82rem"><?php echo e($message); ?><button type="button" class="btn-close" data-bs-dismiss="alert"></button></div><?php endif; ?>
<div class="att-summary"><div class="sum-card present"><div class="sum-icon"><i class="fas fa-check"></i></div><div><div class="sum-value"><?php echo $stats['present']; ?></div><div class="sum-label"><?php echo e(t('hr.present')); ?></div></div></div><div class="sum-card late"><div class="sum-icon"><i class="fas fa-clock"></i></div><div><div class="sum-value"><?php echo $stats['late']; ?></div><div class="sum-label"><?php echo e(t('hr.late')); ?></div></div></div><div class="sum-card absent"><div class="sum-icon"><i class="fas fa-xmark"></i></div><div><div class="sum-value"><?php echo $stats['absent']; ?></div><div class="sum-label"><?php echo e(t('hr.absent')); ?></div></div></div><div class="sum-card leave"><div class="sum-icon"><i class="fas fa-calendar-check"></i></div><div><div class="sum-value"><?php echo $stats['on_leave']; ?></div><div class="sum-label"><?php echo e(t('hr.on_leave')); ?></div></div></div></div>
<div class="att-toolbar"><div class="search"><i class="fas fa-search"></i><input type="search" id="employeeSearch" placeholder="البحث عن موظف..." autocomplete="off"></div><select id="departmentFilter"><option value="">كل الأقسام</option><?php $departments=[];foreach($employees as $e){if(!empty($e['dept_name']))$departments[$e['department_id']]=$e['dept_name'];}foreach($departments as $d): ?><option value="<?php echo htmlspecialchars((string)$d); ?>"><?php echo htmlspecialchars($d); ?></option><?php endforeach; ?></select><select id="statusFilter"><option value="">كل الحالات</option><option value="present"><?php echo e(t('hr.present')); ?></option><option value="late"><?php echo e(t('hr.late')); ?></option><option value="absent"><?php echo e(t('hr.absent')); ?></option><option value="on_leave"><?php echo e(t('hr.on_leave')); ?></option></select></div>
<div class="att-panel"><div class="att-panel-head"><div class="att-panel-title"><i class="fas fa-list-check me-1"></i><?php echo e(t('hr.attendance_records',['date'=>date('Y-m-d',strtotime($selected_date))])); ?></div><span class="att-count"><?php echo e(t('hr.active_employee_count',['count'=>count($employees)])); ?></span></div><div class="table-responsive"><table class="att-table" id="attendanceTable"><thead><tr><th><?php echo e(t('hr.employee')); ?></th><th><?php echo e(t('groups.group')); ?></th><th><?php echo e(t('hr.check_in')); ?></th><th><?php echo e(t('hr.check_out')); ?></th><th>نمط العمل</th><th><?php echo e(t('common.status')); ?></th><th class="text-end"><?php echo e(t('common.actions')); ?></th></tr></thead><tbody>
<?php if(empty($employees)): ?><tr><td colspan="7" class="empty-row"><i class="fas fa-users-slash"></i><?php echo e(t('hr.no_active_employees')); ?></td></tr><?php else: foreach($employees as $emp): $att=$attendance_records[$emp['id']]??null;$status=$att['status']??'absent';$work_mode=$att['work_mode']??'';$initial=mb_substr(trim((string)$emp['full_name']),0,1,'UTF-8');$statusClass=['present'=>'present','late'=>'late','absent'=>'absent','on_leave'=>'leave','half_day'=>'empty'];$statusIcon=['present'=>'fa-check','late'=>'fa-clock','absent'=>'fa-xmark','on_leave'=>'fa-calendar-check','half_day'=>'fa-minus'];$statusLabel=['present'=>'hr.present','late'=>'hr.late','absent'=>'hr.absent','on_leave'=>'hr.on_leave','half_day'=>'hr.half_day']; ?>
<tr data-name="<?php echo htmlspecialchars(mb_strtolower((string)$emp['full_name'],'UTF-8')); ?>" data-dept="<?php echo htmlspecialchars((string)($emp['dept_name']??'')); ?>" data-status="<?php echo htmlspecialchars($status); ?>"><td><div class="employee"><div class="avatar"><?php echo htmlspecialchars($initial); ?></div><div><div class="employee-name"><?php echo htmlspecialchars($emp['full_name']); ?></div><div class="employee-sub">#<?php echo (int)$emp['id']; ?></div></div></div></td><td class="dept"><?php echo htmlspecialchars($emp['dept_name']??'-'); ?></td><td><span class="time-box"><i class="fas fa-arrow-right-to-bracket"></i><?php echo ($att&&$att['check_in'])?substr($att['check_in'],0,5):'--:--'; ?></span></td><td><span class="time-box"><i class="fas fa-arrow-right-from-bracket"></i><?php echo ($att&&$att['check_out'])?substr($att['check_out'],0,5):'--:--'; ?></span></td><td><span class="mode"><?php $modes=['remote'=>'hr.work_mode_remote','onsite'=>'hr.work_mode_onsite','hybrid'=>'hr.work_mode_hybrid'];echo $att?e(t($modes[$work_mode]??'hr.work_mode_remote')):'—'; ?></span></td><td><span class="status <?php echo $statusClass[$status]??'empty'; ?>"><i class="fas <?php echo $statusIcon[$status]??'fa-minus'; ?>"></i><?php echo e(t($statusLabel[$status]??'common.status')); ?></span></td><td class="action-cell text-end"><?php if(!$att||!$att['check_in']): ?><form method="POST" class="action-form"><input type="hidden" name="action" value="check_in"><input type="hidden" name="employee_id" value="<?php echo $emp['id']; ?>"><select name="work_mode" required><option value="remote"><?php echo e(t('hr.work_mode_remote')); ?></option><option value="onsite"><?php echo e(t('hr.work_mode_onsite')); ?></option></select><button class="action-btn action-in" type="submit"><i class="fas fa-right-to-bracket"></i><?php echo e(t('hr.check_in')); ?></button></form><?php elseif(!$att['check_out']): ?><form method="POST" class="action-form"><input type="hidden" name="action" value="check_out"><input type="hidden" name="employee_id" value="<?php echo $emp['id']; ?>"><button class="action-btn action-out" type="submit"><i class="fas fa-right-from-bracket"></i><?php echo e(t('hr.check_out')); ?></button></form><?php else: ?><span class="complete"><i class="fas fa-circle-check"></i><?php echo e(t('hr.complete')); ?></span><?php endif; ?><?php if(!$att||$att['status']==='absent'): ?><form method="POST" class="action-form"><input type="hidden" name="action" value="mark_leave"><input type="hidden" name="employee_id" value="<?php echo $emp['id']; ?>"><button class="action-btn action-leave" type="submit"><i class="fas fa-calendar-check"></i><?php echo e(t('hr.leave')); ?></button></form><?php endif; ?></td></tr>
<?php endforeach; endif; ?></tbody></table></div></div></div>
<script>
document.addEventListener('DOMContentLoaded',function(){const search=document.getElementById('employeeSearch'),dept=document.getElementById('departmentFilter'),status=document.getElementById('statusFilter');function filter(){const q=(search.value||'').trim().toLocaleLowerCase();document.querySelectorAll('#attendanceTable tbody tr[data-name]').forEach(r=>{const okName=!q||r.dataset.name.includes(q),okDept=!dept.value||r.dataset.dept===dept.value,okStatus=!status.value||r.dataset.status===status.value;r.style.display=okName&&okDept&&okStatus?'':'none';});}search.addEventListener('input',filter);dept.addEventListener('change',filter);status.addEventListener('change',filter);});
</script>
